import {curriculumAdditions} from './curriculum-expansion.js';
// Original curriculum for SQL4Learn. Every visible exercise has an executable reference query.
// Never claim that planned modules are already available.
const T=(id,title,prompt,sql,ordered=false)=>({id,title,prompt,sql,ordered});
const L=(id,title,lead,theory,example,question,choices,correct,why,tasks,insight)=>({id,title,lead,theory,example,quiz:{question,choices,correct,why},tasks,insight});
const M=(id,title,subtitle,icon,lessons)=>({id,title,subtitle,icon,lessons});

export const modules=[
 M("start","Первый контакт с данными","Пишем SQL с первого занятия. Без установки программ и получасовых вступлений.","01",[
  L("first-query","Первый SQL за две минуты","SQL — это способ задать вопрос данным и получить таблицу ответа.",[
    "Даже без знакомства со схемой ты уже можешь написать полноценный запрос. SELECT обозначает, какие значения должны появиться в ответе. PostgreSQL сам вычислит результат и вернёт его в виде таблицы.",
    "Начнём с выражения, а не с заучивания списка команд. У каждого полученного столбца есть имя. AS позволяет дать ему понятный псевдоним. Здесь нет FROM, потому что мы пока ничего не читаем из таблицы."
  ],"SELECT 7 + 5 AS result;","Что возвращает запрос SELECT 7 + 5 AS result;?",["Таблицу с одним значением 12","Новый столбец в существующей базе","Ошибку: обязательно нужна таблица"],0,"SELECT без FROM допустим в PostgreSQL и возвращает одну строку с вычисленным выражением.",[
    T("start-1","Первая проверка","Посчитай в SQL, сколько получится при умножении 12 на 8. Назови результат total.", "SELECT 12 * 8 AS total;"),
    T("start-2","Часы работы","Получите длительность смены с 09:00 до 17:00 в часах, одним столбцом hours.", "SELECT 17 - 9 AS hours;"),
    T("start-3","Проверка литералов","Покажи одну строку со значением 'SQL4Learn' и именем столбца platform.", "SELECT 'SQL4Learn' AS platform;")
  ],"Модель: SELECT определяет форму ответа. Отсутствие FROM означает, что исходные строки таблицы не нужны. Это полезный способ отдельно проверять арифметику, преобразования и функции."),
  L("explore-data","Что хранится в таблице","Откроем настоящие заказы нашей учебной службы доставки.",[
    "Таблица orders хранит по одной записи на заказ. Столбцы описывают его номер, покупателя, магазин, сумму, статус и время оформления. FROM указывает, откуда брать строки.",
    "SELECT * удобен для первоначального знакомства с данными: звёздочка означает все столбцы. Но для постоянного отчёта лучше перечислять только необходимые поля — так структура ответа не изменится неожиданно."
  ],"SELECT * FROM orders;","Что означает звёздочка в SELECT *?",["Все таблицы базы","Все столбцы выбранного источника","Только обязательные столбцы"],1,"Звёздочка возвращает все поля в результирующей таблице.",[
    T("start-4","Найди факты","Посмотри все доступные записи о заказах, без отбора строк и ограничения полей.","SELECT * FROM orders;"),
    T("start-5","Список магазинов","Изучи весь справочник магазинов, включая города и названия.","SELECT * FROM stores;")
  ],"Прежде чем строить отчёт, ответь: что означает одна строка таблицы? В orders одна строка — один заказ, в order_items — одна товарная позиция. Путаница этих уровней приводит к неправильным суммам."),
  L("columns","Нужные столбцы и понятные имена","От исследовательской выборки переходим к аккуратному отчёту.",[
    "В рабочем запросе почти всегда нужны только определённые атрибуты. Перечисляй их после SELECT через запятую — порядок перечисления станет порядком столбцов результата.",
    "Псевдонимы через AS не переименовывают исходные столбцы. Они задают удобные названия в текущем результате. Это особенно важно, когда отчёт передаётся в Metabase или другой BI-инструмент."
  ],"SELECT order_id AS id, amount AS revenue\nFROM orders;","Какой смысл у AS revenue?",["Переименовывает столбец физической таблицы","Переименовывает столбец результата","Создаёт таблицу revenue"],1,"AS задаёт имя выражения в выводе текущего SELECT.",[
    T("start-6","Короткая ведомость","Для проверки финансов выгрузи номера заказов и их суммы, без дополнительных полей.","SELECT order_id, amount FROM orders;"),
    T("start-7","Отчёт для коллеги","Подготовь список заказов с колонками id и total, отражающими номер и сумму.","SELECT order_id AS id, amount AS total FROM orders;"),
    T("start-8","Контакты клиентов","Подготовь список имён клиентов и городов их проживания.","SELECT customer_name, city FROM customers;")
  ],"Выдача SELECT — отдельная таблица. Алиас может изменить её заголовок, но не сами исходные данные. Для аналитика явный набор выходных полей — часть контракта отчёта."),
  L("distinct-order","Повторы и определённый порядок","Получить уникальный список — не то же самое, что отсортировать его.",[
    "DISTINCT убирает повторяющиеся комбинации выбранных полей. Если выбрать city, получим города без дублей. Но DISTINCT по двум полям проверяет уникальность уже пары значений.",
    "ORDER BY определяет порядок результата. DESC означает по убыванию, ASC — по возрастанию. При одинаковых значениях полезно добавить второй ключ — уникальный идентификатор, чтобы ответ был воспроизводимым."
  ],"SELECT DISTINCT city\nFROM customers\nORDER BY city;","Что произойдёт с двумя строками с одинаковым городом при SELECT DISTINCT city?",["Останутся обе","Останется одна","SQL выдаст ошибку"],1,"DISTINCT оставит одно значение города; ORDER BY только упорядочит результат.",[
    T("start-9","География клиентов","Назови все города, в которых живут наши клиенты, без повторов и по алфавиту.","SELECT DISTINCT city FROM customers ORDER BY city;",true),
    T("start-10","Самые крупные счета","Подготовь суммы всех заказов от большей к меньшей, а при равенстве отсортируй по номеру заказа.","SELECT amount, order_id FROM orders ORDER BY amount DESC, order_id;",true)
  ],"DISTINCT не исправляет случайное размножение строк при JOIN. Сначала пойми, почему появился повтор, затем реши, имеет ли он смысл для бизнес-задачи.")
 ,
  L("limit-top","LIMIT и воспроизводимый топ","Отчёт «первые пять» ничего не значит, пока мы не объяснили, какие именно пять.",[
 "LIMIT ограничивает количество строк ответа, но не определяет, какие строки попадут в результат. Сначала сформулируй критерий и запиши ORDER BY, затем применяй LIMIT. Если ключи сортировки равны, добавь уникальный идентификатор, чтобы ответ был воспроизводимым.",
 "OFFSET пропускает заданное число строк уже после сортировки. Это удобно для учебной второй страницы, но при появлении новых записей в реальной базе страницы могут сдвигаться. Для серьёзной пагинации часто выбирают способ с указанием последнего ключа."
 ],"SELECT order_id,amount\nFROM orders\nORDER BY amount DESC,order_id\nLIMIT 3;","Почему LIMIT 3 без ORDER BY не гарантирует три самых дорогих заказа?",["PostgreSQL может отдать любые три строки, если порядок не задан","LIMIT автоматически сортирует по первичному ключу","LIMIT нельзя использовать с числами"],0,"LIMIT отсекает строки, но порядок задаёт только ORDER BY.",[
  T("start-11","Три самых крупных заказа","Покажи номера и суммы трёх самых дорогих заказов. При одинаковых суммах выше ставь заказ с меньшим номером.","SELECT order_id,amount FROM orders ORDER BY amount DESC,order_id LIMIT 3;",true),
  T("start-12","Первый список покупателей","Для проверки регистрации покажи идентификаторы и имена пяти самых ранних клиентов по дате регистрации, а при равенстве — по идентификатору.","SELECT customer_id,customer_name FROM customers ORDER BY registered_at,customer_id LIMIT 5;",true),
  T("start-13","Вторая страница заказов","Выведи четвёртый, пятый и шестой по номеру заказ. Покажи order_id и отсортируй строки по его возрастанию.","SELECT order_id FROM orders ORDER BY order_id LIMIT 3 OFFSET 3;",true)
 ],"LIMIT 5 — ещё не «топ-5», пока не определён смысл порядка. Сравни результат без сортировки и с явно заданной сортировкой: на другом наборе данных строки могут не совпасть."),
 ]),
 M("filter","Отбираем нужное","Фильтруем строки, задаём границы, работаем с NULL и текстом.","02",[
  L("where-basic","WHERE — условия для строк","Не все заказы одинаково важны для одного отчёта.",[
    "WHERE оставляет только те исходные строки, для которых условие истинно. Сравнивать можно числа, даты и текст. Строковые значения записываются в одинарных кавычках.",
    "Граница имеет значение: > 1000 и >= 1000 отличаются одним значением. Чтобы не ошибиться, перед выполнением сформулируй, входит ли сам порог в выборку."
  ],"SELECT order_id, amount\nFROM orders\nWHERE amount >= 1000;","Пройдёт ли заказ на 1000 рублей условие amount > 1000?",["Да","Нет","Только при ORDER BY"],1,"Строгое больше исключает сам порог.",[
    T("filter-1","Дорогое обслуживание","Найди все заказы строго дороже 1500 рублей. Для сверки нужны их номера и суммы.","SELECT order_id, amount FROM orders WHERE amount > 1500;"),
    T("filter-2","Завершённые доставки","Подготовь номера и статусы заказов, которые уже доставлены.","SELECT order_id, status FROM orders WHERE status = 'delivered';"),
    T("filter-3","Проблемы маршрутизации","Собери номера заказов, которые были отменены.","SELECT order_id FROM orders WHERE status = 'cancelled';")
  ],"WHERE действует до группировки. Оно удаляет исходные записи, поэтому влияет и на будущий COUNT, и на будущую сумму."),
  L("and-or","AND, OR и скобки","Несколько условий можно объединить — и легко ошибиться с приоритетами.",[
    "AND требует выполнения обоих условий, OR — хотя бы одного. Операторы не равнозначны: AND имеет более высокий приоритет, поэтому в сложных бизнес-условиях ставь скобки.",
    "Проверяй пограничные кейсы. Условие статус delivered ИЛИ cancelled И сумма больше 1000 без скобок может случайно применить сумму только ко второму статусу."
  ],"SELECT order_id, status, amount\nFROM orders\nWHERE status = 'delivered' AND amount > 1000;","Как безопаснее записать смешанную логику AND и OR?",["Без скобок, SQL сам поймёт бизнес-смысл","Со скобками, отражающими нужную группировку","Всегда только через два WHERE"],1,"Скобки делают условие однозначным и читаемым.",[
    T("filter-4","Доставки высокого чека","Подготовь номера доставленных заказов на сумму от 1500 рублей включительно.","SELECT order_id FROM orders WHERE status='delivered' AND amount >= 1500;"),
    T("filter-5","Завершённые и отменённые","Покажи номера и статусы заказов, которые либо доставлены, либо отменены.","SELECT order_id,status FROM orders WHERE status='delivered' OR status='cancelled';"),
    T("filter-6","Операционные исключения","Найди заказы на сумму более 1000, которые доставлены или всё ещё находятся в пути. Достаточно номера и статуса.","SELECT order_id,status FROM orders WHERE amount > 1000 AND (status='delivered' OR status='in_transit');")
  ],"SQL возвращает строки, удовлетворяющие логическому выражению. В отличие от человеческого языка, в нём невозможно «догадаться», к чему относится спорный фрагмент условия."),
  L("in-like","Списки значений и поиск по тексту","Когда нужно выбрать сразу несколько городов или найти похожие имена.",[
    "IN проверяет, входит ли значение в набор. Это более короткая и ясная запись нескольких условий с OR по одному полю.",
    "LIKE сравнивает текст с шаблоном: % означает любое число символов, _ — один символ. ILIKE в PostgreSQL игнорирует регистр. Шаблон ищет совпадение, а не «понимает» смысл имени."
  ],"SELECT customer_name, city\nFROM customers\nWHERE city IN ('Москва', 'Казань');","Что делает шаблон ILIKE 'ма%'?",["Выбирает имена, начинающиеся на «ма» без учёта регистра","Выбирает имена только из двух символов","Превращает все значения в нижний регистр"],0,"ILIKE сопоставляет значения без учёта регистра, а % покрывает остаток строки.",[
    T("filter-7","Регионы экспансии","Подготовь имена и города клиентов, живущих в Москве или Казани.","SELECT customer_name,city FROM customers WHERE city IN ('Москва','Казань');"),
    T("filter-8","Поиск клиента","Найди клиентов, чьё имя начинается с «ма», независимо от регистра. Покажи имена.","SELECT customer_name FROM customers WHERE customer_name ILIKE 'ма%';"),
    T("filter-9","Соседние города","Подготовь список названий магазинов из Москвы и Орла.","SELECT store_name FROM stores WHERE city IN ('Москва','Орёл');")
  ],"Фильтрация строк не создаёт новых записей и не исправляет опечатки. Имена и адреса могут отличаться пробелами, регистром и вариантом написания — это отдельная задача качества данных."),
  L("null-range","NULL и числовые диапазоны","Отсутствие значения — не ноль и не пустая строка.",[
    "NULL обозначает неизвестное или отсутствующее значение. Сравнение courier_id = NULL не даст TRUE: используем IS NULL. Аналогично IS NOT NULL находит назначенных исполнителей.",
    "BETWEEN включает обе числовые границы. Если в результат нужно поставить запасное значение вместо NULL, используй COALESCE(courier_id,0): он вернёт 0 только для неназначенного курьера. Исходная таблица при этом не изменится."
  ],"SELECT order_id\nFROM orders\nWHERE courier_id IS NULL;","Что вернёт сравнение NULL = NULL в условии WHERE?",["TRUE","FALSE","UNKNOWN, а значит строка не пройдёт WHERE"],2,"В SQL NULL нельзя сравнивать обычным равенством: результат UNKNOWN.",[
    T("filter-10","Без назначенного курьера","Найди номера заказов, которым ещё не назначен курьер.","SELECT order_id FROM orders WHERE courier_id IS NULL;"),
    T("filter-12","Заказы в нужном диапазоне","Найди номера и суммы заказов в диапазоне от 500 до 1500 рублей включительно.","SELECT order_id,amount FROM orders WHERE amount BETWEEN 500 AND 1500;"),
    T("filter-13","Список назначений","Для каждого заказа покажи order_id и assigned_courier — идентификатор курьера, либо 0, если курьер ещё не назначен.","SELECT order_id,COALESCE(courier_id,0) AS assigned_courier FROM orders;")
  ],"WHERE пропускает только TRUE. Значения FALSE и UNKNOWN обе не проходят фильтр; это объясняет многие неожиданные пропуски строк в отчётах.")
 ,
  L("case-basic","CASE: превращаем правила в категории","Аналитический сегмент — правило для каждой отдельной строки.",[
 "CASE WHEN условие THEN значение ... ELSE значение END создаёт вычисляемый столбец. Это не фильтр: исходная строка остаётся, а CASE возвращает результат первой истинной ветки. Если ни одно условие не подошло и ELSE не указан, будет NULL.",
 "Для категорий проверь все границы: «до 1000 включительно» и «свыше 1000» покрывают все суммы без пересечения. Порядок WHEN важен — после первого TRUE остальные условия больше не проверяются. NULL нельзя обнаружить обычным равенством."
 ],"SELECT order_id,\n CASE WHEN amount <= 1000 THEN 'small' ELSE 'large' END AS segment\nFROM orders;","Какая ветка CASE сработает, если два WHEN одновременно истинны?",["Последняя истинная ветка","Первая истинная ветка","SQL объединит оба результата"],1,"CASE выбирает первое истинное WHEN по порядку написания.",[
  T("case-1","Сегментация чеков","Для каждого заказа покажи номер и segment: small при сумме до 1000 рублей включительно, иначе large.","SELECT order_id,CASE WHEN amount<=1000 THEN 'small' ELSE 'large' END AS segment FROM orders;"),
  T("case-2","Назначения курьеров","Для каждого заказа покажи номер и courier_state: unassigned, если курьер не назначен, иначе assigned.","SELECT order_id,CASE WHEN courier_id IS NULL THEN 'unassigned' ELSE 'assigned' END AS courier_state FROM orders;"),
  T("case-3","Три размера чека","Для каждого заказа покажи номер и price_band: low — до 500 включительно, medium — свыше 500 и до 1500 включительно, high — свыше 1500.","SELECT order_id,CASE WHEN amount<=500 THEN 'low' WHEN amount<=1500 THEN 'medium' ELSE 'high' END AS price_band FROM orders;")
 ],"CASE вычисляет значение на строке. GROUP BY позже позволит свести категории в статистику, но сначала важно, чтобы сама классификация была полной и однозначной."),
 ]),
 M("aggregate","Агрегации и метрики","Переходим от отдельных строк к количеству, выручке и средним.","03",[
  L("aggr-basic","COUNT, SUM и AVG","Теперь руководству нужен не список заказов, а показатели бизнеса.",[
    "COUNT(*) считает все строки. COUNT(column) пропускает NULL, а COUNT(DISTINCT column) считает уникальные непустые значения. SUM и AVG также игнорируют NULL.",
    "Агрегат без GROUP BY создаёт одну группу из всех подходящих строк. Важно заранее определить, какие статусы входят в понятие выручки."
  ],"SELECT COUNT(*) AS orders_count,\n       SUM(amount) AS total_amount\nFROM orders;","Чем COUNT(*) отличается от COUNT(courier_id)?",["Ничем","COUNT(courier_id) пропускает NULL","COUNT(*) исключает повторяющиеся строки"],1,"COUNT(column) учитывает только непустые значения столбца.",[
    T("aggr-1","Пульс бизнеса","Подготовь число всех заказов. Поле результата назови orders_count.","SELECT COUNT(*) AS orders_count FROM orders;"),
    T("aggr-2","Выручка завершённых доставок","Рассчитай сумму только доставленных заказов. Назови показатель revenue.","SELECT SUM(amount) AS revenue FROM orders WHERE status='delivered';"),
    T("aggr-3","Средний доставленный чек","Посчитай среднюю сумму доставленного заказа с названием avg_check.","SELECT AVG(amount) AS avg_check FROM orders WHERE status='delivered';")
  ],"Если заказ отменён, включать его сумму в выручку обычно нельзя. Сначала запиши бизнес-правило, затем формулу. Корректный SUM без корректного WHERE не делает метрику правильной."),
  L("group-by","GROUP BY: меняем зерно","Одна строка исходных данных превращается в одну строку по группе.",[
    "GROUP BY объединяет записи с одинаковыми ключами. После группировки каждое поле результата должно либо быть ключом группы, либо агрегироваться.",
    "Одна строка ответа «город → выручка» означает уже один город, а не заказ. Именно этот переход зерна нужно понимать, прежде чем добавлять JOIN."
  ],"SELECT status, COUNT(*) AS orders_count\nFROM orders\nGROUP BY status\nORDER BY status;","Какое зерно у SELECT status, COUNT(*) ... GROUP BY status?",["Одна строка на заказ","Одна строка на статус","Одна строка на клиента"],1,"Группировка сворачивает исходные строки до уникальных сочетаний ключей.",[
    T("aggr-4","Статусная сводка","Посчитай количество заказов по каждому статусу. Покажи статус и показатель orders_count.","SELECT status, COUNT(*) AS orders_count FROM orders GROUP BY status;"),
    T("aggr-5","Магазины в разрезе","Подготовь общую сумму заказов по каждому идентификатору магазина. Назови показатель total_amount.","SELECT store_id,SUM(amount) AS total_amount FROM orders GROUP BY store_id;"),
    T("aggr-6","Активность покупателей","Посчитай число заказов у каждого покупателя, включая покупателей с единственным заказом. Нужны его идентификатор и orders_count.","SELECT customer_id,COUNT(*) AS orders_count FROM orders GROUP BY customer_id;")
  ],"При GROUP BY не надо добавлять в список произвольный уникальный ID заказа: это вернёт зерно «заказ» и разрушит смысл агрегированного отчёта."),
  L("having","HAVING: фильтр готовых групп","Сравнивать итог группы и фильтровать отдельные строки — не одно и то же.",[
    "WHERE действует на исходные строки; HAVING отбирает уже рассчитанные группы. Например, сначала считаем заказы на магазин, потом оставляем магазины с числом заказов больше двух.",
    "Типичная ошибка — использовать COUNT в WHERE, хотя на этом этапе группы ещё не вычислены."
  ],"SELECT store_id, COUNT(*) AS orders_count\nFROM orders\nGROUP BY store_id\nHAVING COUNT(*) >= 3;","Где применяется условие COUNT(*) >= 3 к готовым группам?",["WHERE","HAVING","JOIN"],1,"HAVING работает после логического этапа GROUP BY.",[
    T("aggr-7","Нагрузка на магазины","Найди идентификаторы магазинов, у которых не менее трёх заказов. Покажи идентификатор и orders_count.","SELECT store_id, COUNT(*) AS orders_count FROM orders GROUP BY store_id HAVING COUNT(*) >= 3;"),
    T("aggr-8","Крупные покупатели","Найди покупателей с суммарной стоимостью заказов строго больше 2000. Покажи идентификатор и total_amount.","SELECT customer_id,SUM(amount) AS total_amount FROM orders GROUP BY customer_id HAVING SUM(amount)>2000;")
  ],"Можно написать похожие формулы в WHERE и HAVING, но смысл различается: WHERE меняет состав группы, а HAVING только решает, показывать ли уже посчитанную группу."),
  L("filter-case","Условные показатели и CASE","Несколько метрик с разными условиями в одном отчёте.",[
    "FILTER позволяет одной группе одновременно считать все заказы, доставленные и отменённые. CASE создаёт условное значение — например категорию чека.",
    "Порядок WHEN в CASE важен: сработает первая истинная ветка. Границы сегментов должны не пересекаться, если этого требует бизнес."
  ],"SELECT store_id,\n COUNT(*) AS all_orders,\n COUNT(*) FILTER (WHERE status='delivered') AS delivered\nFROM orders\nGROUP BY store_id;","Зачем нужен FILTER внутри агрегата?",["Отбирает строки для конкретной метрики, не удаляя их для остальных","Удаляет все группы","Меняет порядок строк"],0,"FILTER действует только на тот агрегат, к которому относится.",[
    T("aggr-9","Контроль качества доставок","По каждому магазину покажи его идентификатор, число всех заказов all_orders и количество доставленных delivered.","SELECT store_id,COUNT(*) AS all_orders,COUNT(*) FILTER(WHERE status='delivered') AS delivered FROM orders GROUP BY store_id;"),
    T("aggr-10","Сегментация чеков","Посчитай число заказов в категориях: economy — до 1000 включительно; premium — свыше 1000. Покажи категорию category и количество orders_count.","SELECT CASE WHEN amount<=1000 THEN 'economy' ELSE 'premium' END AS category, COUNT(*) AS orders_count FROM orders GROUP BY CASE WHEN amount<=1000 THEN 'economy' ELSE 'premium' END;")
  ],"Условные метрики должны делить понятный исходный набор строк. Если добавить глобальный WHERE status='delivered', показатель all_orders перестанет означать «все заказы».")
 ]),
 M("joins","Соединения без ошибок","Как соединять факты и справочники, не удваивая деньги.","04",[
  L("inner","INNER JOIN и ключи","Подтягиваем название магазина к каждой записи о заказе.",[
    "JOIN сопоставляет строки по условию ON. Для одного заказа существует один магазин, поэтому соединение заказов со справочником магазинов обычно сохраняет число заказов.",
    "Но если ключ на правой стороне не уникален, одна строка может размножиться. Перед любой агрегацией проверяй кардинальность."
  ],"SELECT o.order_id, s.store_name\nFROM orders o\nJOIN stores s ON s.store_id=o.store_id;","Когда INNER JOIN исключает заказ?",["Когда нет совпадающей строки справа","Когда у заказа большая сумма","Никогда"],0,"INNER JOIN оставляет только пары строк с совпавшим условием ON.",[
    T("join-1","Читаемый отчёт","Подготовь номера заказов и названия магазинов, в которых они оформлены.","SELECT o.order_id,s.store_name FROM orders o JOIN stores s ON s.store_id=o.store_id;"),
    T("join-2","География заказчиков","Для каждого заказа покажи его номер и город клиента.","SELECT o.order_id,c.city FROM orders o JOIN customers c ON c.customer_id=o.customer_id;")
  ],"Зерно после JOIN определяется не названием конструкции, а ключами. Дубли в справочнике способны удвоить выручку, хотя запрос не содержит ни одной синтаксической ошибки."),
  L("left","LEFT JOIN и потерянные строки","Иногда отсутствие связанного события — именно то, что требуется увидеть.",[
    "LEFT JOIN сохраняет все строки левого источника, даже если справа нет совпадения. Правые столбцы таких строк становятся NULL.",
    "Если после LEFT JOIN поставить WHERE по полю правой таблицы, можно удалить NULL-строки и незаметно превратить отчёт во внутреннее соединение."
  ],"SELECT s.store_name, o.order_id\nFROM stores s\nLEFT JOIN orders o ON o.store_id=s.store_id;","Что произойдёт с магазином без заказов при LEFT JOIN stores → orders?",["Пропадёт","Останется со значением NULL в полях заказа","Создаст фиктивный заказ"],1,"LEFT JOIN сохраняет левую строку без совпадения справа.",[
    T("join-3","Все магазины компании","Покажи названия всех магазинов и номера связанных заказов, включая магазины без единого заказа.","SELECT s.store_name,o.order_id FROM stores s LEFT JOIN orders o ON o.store_id=s.store_id;"),
    T("join-4","Справедливый учёт","Для каждого магазина покажи его название и число заказов orders_count, даже если заказов пока нет.","SELECT s.store_name,COUNT(o.order_id) AS orders_count FROM stores s LEFT JOIN orders o ON o.store_id=s.store_id GROUP BY s.store_id,s.store_name;")
  ],"COUNT(*) после LEFT JOIN может дать единицу для магазина без заказов из-за сохранённой пустой строки. Для подсчёта совпадений считай непустой первичный ключ правой таблицы."),
  L("anti","Кто остался без заказов","Ищем отсутствие совпадения, а не только наличие.",[
    "Антисоединение отвечает на вопрос «у кого нет связанных записей?». Используем знакомый LEFT JOIN: присоединяем заказы к клиентам, затем выбираем строки, у которых первичный ключ заказа оказался NULL. Такое значение возникает, когда справа нет совпадения.",
    "Для проверки отсутствия выбирай непустой ключ правой таблицы, а не любой nullable-столбец: NULL в настоящей записи может иметь иной смысл. Позже мы познакомимся с NOT EXISTS — альтернативным способом через подзапрос. Его пока не требуется использовать."
  ],"SELECT c.customer_id,c.customer_name\nFROM customers c\nLEFT JOIN orders o ON o.customer_id=c.customer_id\nWHERE o.order_id IS NULL;","Почему после LEFT JOIN проверяем o.order_id IS NULL?",["Отсутствующий правый первичный ключ означает отсутствие совпадения","Так проверяется сумма заказов","LEFT JOIN всегда создаёт реальный заказ"],0,"Первичный ключ реального заказа не может быть NULL. После LEFT JOIN значение NULL справа означает, что совпадения не нашлось.",[
    T("join-5","Неактивные покупатели","Найди имена клиентов, которые ещё ни разу не оформляли заказ.","SELECT c.customer_name FROM customers c LEFT JOIN orders o ON o.customer_id=c.customer_id WHERE o.order_id IS NULL;"),
    T("join-6","Магазины без продаж","Назови магазины, в которых ещё не было заказов.","SELECT s.store_name FROM stores s LEFT JOIN orders o ON o.store_id=s.store_id WHERE o.order_id IS NULL;")
  ],"Отсутствие заказа должно быть результатом логики связей, а не разницей между двумя независимо полученными списками, где можно перепутать ключи."),
  L("fanout","Fan-out: как случайно удвоить выручку","Самая опасная ошибка JOIN не выдаёт ошибку SQL. Она тихо увеличивает цифры.",[
    "У заказа может быть несколько позиций. После соединения orders и order_items один заказ повторяется столько раз, сколько у него позиций. SUM(o.amount) после такого JOIN завысит выручку.",
    "Для числа товарных позиций можно считать строки order_items, а для суммы заказа нужно заранее выбрать правильное зерно. Часто помогают две отдельные агрегации: одна по заказам, другая по позициям."
  ],"SELECT o.order_id,\n COUNT(oi.item_id) AS item_positions\nFROM orders o\nLEFT JOIN order_items oi ON oi.order_id=o.order_id\nGROUP BY o.order_id;","Если у одного заказа три позиции, сколько раз его сумма повторится после обычного JOIN с позициями?",["Один раз","Три раза","Ни разу"],1,"Соединение один-ко-многим возвращает одну строку для каждого совпадения справа.",[
    T("join-7","Контроль позиции","Для каждого заказа покажи его номер и количество товарных позиций positions, включая заказы без позиций.","SELECT o.order_id,COUNT(oi.item_id) AS positions FROM orders o LEFT JOIN order_items oi ON oi.order_id=o.order_id GROUP BY o.order_id;"),
    T("join-8","Сумма товаров","Для каждого заказа покажи номер и расчётную стоимость всех его позиций items_total. Для заказов без позиций должна получиться сумма 0.","SELECT o.order_id,COALESCE(SUM(oi.quantity*oi.unit_price),0) AS items_total FROM orders o LEFT JOIN order_items oi ON oi.order_id=o.order_id GROUP BY o.order_id;")
  ],"SUM(DISTINCT amount) не исправляет fan-out: два разных заказа могут иметь одинаковую сумму. Уникальность бизнес-факта задаётся order_id, а не значением денег.")
 ,
  L("logical-order","Почему SQL пишется не в порядке выполнения","Изучаем путь данных от исходных строк до готовой аналитической таблицы.",[
 "SQL — декларативный язык: мы описываем, что хотим получить, а не даём последовательные инструкции процессору. Запрос начинается с SELECT, потому что так видна форма результата. Но логическая обработка начинается с FROM и JOIN, затем WHERE оставляет подходящие исходные строки, GROUP BY объединяет их, HAVING оставляет нужные группы.",
 "После формирования групп вычисляется SELECT, затем DISTINCT удаляет повторы, ORDER BY сортирует и LIMIT/OFFSET ограничивает результат. Это логическая модель смысла запроса: физический план PostgreSQL может выполнять операции в другом порядке, но обязан сохранять тот же результат.",
 "Теперь понятно, почему нельзя использовать COUNT(*) для фильтрации групп в WHERE: групп ещё не существует. А псевдоним из SELECT уже доступен в ORDER BY, потому что логически сортировка стоит позже."
 ],"SELECT store_id,COUNT(*) AS delivered_orders\nFROM orders\nWHERE status='delivered'\nGROUP BY store_id\nHAVING COUNT(*) >= 2\nORDER BY delivered_orders DESC,store_id\nLIMIT 3;","Почему COUNT(*) нельзя использовать в WHERE для отбора групп?",["WHERE действует до GROUP BY, когда итогов групп ещё нет","COUNT работает только с JOIN","SELECT обязательно должен стоять после FROM в тексте"],0,"Фильтр исходных строк — WHERE, фильтр уже вычисленных групп — HAVING.",[
  T("logic-1","Лидеры доставок","Посчитай доставленные заказы orders_count по магазинам с минимум двумя доставками. Покажи три магазина с наибольшим количеством, а при равенстве ставь меньший store_id первым. Верни store_id и orders_count.","SELECT store_id,COUNT(*) AS orders_count FROM orders WHERE status='delivered' GROUP BY store_id HAVING COUNT(*)>=2 ORDER BY orders_count DESC,store_id LIMIT 3;",true),
  T("logic-2","Все магазины в отчёте","Подготовь названия всех магазинов и количество их заказов orders_count. Пустые магазины должны присутствовать; сортируй по убыванию числа заказов и затем по названию.","SELECT s.store_name,COUNT(o.order_id) AS orders_count FROM stores s LEFT JOIN orders o ON o.store_id=s.store_id GROUP BY s.store_id,s.store_name ORDER BY orders_count DESC,s.store_name;",true),
  T("logic-3","Самые ценные покупатели","Найди двух покупателей с максимальной суммой доставленных заказов. Покажи customer_id и revenue, при равенстве суммы первым ставь меньший идентификатор.","SELECT customer_id,SUM(amount) AS revenue FROM orders WHERE status='delivered' GROUP BY customer_id ORDER BY revenue DESC,customer_id LIMIT 2;",true)
 ],"Логический порядок — модель смысла, а не точная трассировка физического плана. Ошибку надо искать на конкретном шаге: соединение строк, фильтр, группировка, вычисление, сортировка или ограничение."),
 ]),
 M("dates","Даты и временные отчёты","Периоды, календарные недели, интервалы, дни без продаж и правильные границы.","05",[
  L("date-types","DATE и TIMESTAMP: не путай день и момент","Дата отчёта и точное время оформления заказа — разные вещи.",[
    "DATE хранит календарный день, TIMESTAMP — дату и местное время без сведений о часовом поясе, а TIMESTAMPTZ — точный момент времени с преобразованием для отображения. В учебной orders поле ordered_at имеет тип TIMESTAMP: не следует приписывать ему часовой пояс, которого нет в данных.",
    "Преобразование ordered_at::date берёт календарную дату. Для фильтра по полным суткам лучше использовать полуоткрытый диапазон: время >= полуночь первого дня и < полуночь следующего. Так не теряются события после 23:59:59 с дробной частью секунды и могут использоваться индексы по исходному полю."
  ],"SELECT order_id, ordered_at::date AS order_date\nFROM orders\nWHERE ordered_at >= TIMESTAMP '2026-04-05'\n  AND ordered_at < TIMESTAMP '2026-04-06';",
  "Почему фильтр по суткам лучше завершать условием < начало следующего дня?",["Чтобы исключить начало отчётного дня","Чтобы не потерять дробные секунды в конце суток","Чтобы SQL всегда быстрее работал на любой таблице"],1,"Граница следующего дня задаёт точный полуоткрытый период для любого времени внутри суток.",[
    T("filter-11","Неделя продаж","Покажи номера заказов, оформленных с 1 по 7 апреля 2026 года включительно, не зависимо от времени суток.","SELECT order_id FROM orders WHERE ordered_at >= TIMESTAMP '2026-04-01' AND ordered_at < TIMESTAMP '2026-04-08';"),
    T("date-1","Доставка 5 апреля","Для сверки получи номера всех заказов, оформленных в течение 5 апреля 2026 года, включая любые часы и минуты.","SELECT order_id FROM orders WHERE ordered_at >= TIMESTAMP '2026-04-05' AND ordered_at < TIMESTAMP '2026-04-06';"),
    T("date-2","Даты оформления","Для каждого заказа подготовь его номер и календарную дату оформления в столбце order_date без времени.","SELECT order_id,ordered_at::date AS order_date FROM orders;"),
    T("date-3","Новая рабочая неделя","Найди номера заказов, оформленных начиная с полуночи 7 апреля 2026 года включительно.","SELECT order_id FROM orders WHERE ordered_at >= TIMESTAMP '2026-04-07';")
  ],"DATE не означает TIMESTAMP, у которого часы просто скрыты интерфейсом. Для проверяемого отчёта явно указывай, какая дата считается отчётной и какой момент завершает период."),
  L("date-trunc","DATE_TRUNC: собираем отчёты по дням и неделям","Чтобы сравнить периоды, нужно сначала договориться об их границах.",[
    "DATE_TRUNC('day', ordered_at) приводит время к началу дня, 'week' — к началу недели, 'month' — к началу месяца. В PostgreSQL неделя DATE_TRUNC начинается в понедельник. Если отчёту нужна именно календарная дата, преобразуй результат к ::date.",
    "При GROUP BY по началу периода одна строка теперь означает день или неделю, а не заказ. Но обычная группировка показывает только периоды с фактическими заказами: отсутствующие дни надо дополнить отдельным календарём."
  ],"SELECT DATE_TRUNC('day',ordered_at)::date AS day,\n       COUNT(*) AS orders_count\nFROM orders\nGROUP BY DATE_TRUNC('day',ordered_at)::date\nORDER BY day;",
  "Какое зерно будет у GROUP BY DATE_TRUNC('day', ordered_at)?",["Одна строка на заказ","Одна строка на календарный день с заказами","Одна строка на клиента"],1,"Все заказы одного дня входят в одну группу, а дни без фактов не появляются автоматически.",[
    T("date-4","Дневная нагрузка","Подготовь по календарным дням с заказами число оформлений orders_count. Покажи дату day и количество, отсортируй даты по возрастанию.","SELECT ordered_at::date AS day,COUNT(*) AS orders_count FROM orders GROUP BY ordered_at::date ORDER BY day;",true),
    T("date-5","Дневная выручка","Для каждого дня, в который была хотя бы одна доставленная покупка, рассчитай сумму доставленных заказов revenue. Покажи дату day и значение.","SELECT ordered_at::date AS day,SUM(amount) AS revenue FROM orders WHERE status='delivered' GROUP BY ordered_at::date;"),
    T("date-6","Отчёт по неделям","Посчитай число всех заказов в каждой календарной неделе. Верни дату понедельника week и orders_count, недели по возрастанию.","SELECT DATE_TRUNC('week',ordered_at)::date AS week,COUNT(*) AS orders_count FROM orders GROUP BY DATE_TRUNC('week',ordered_at)::date ORDER BY week;",true)
  ],"Для фактов без событий календарная группировка не создаёт нулевые строки. Разница «ноль продаж» и «неизвестно, были ли данные» должна обсуждаться отдельно."),
  L("extract-dow","EXTRACT: час, день недели и месяц","Из временной метки можно получить признак для анализа нагрузки.",[
    "EXTRACT берёт часть даты и времени: HOUR, MONTH, ISODOW. ISODOW в PostgreSQL возвращает понедельник = 1, ..., воскресенье = 7. Это удобнее для рабочих недель, чем DOW (в котором воскресенье = 0).",
    "Группировка по часу или дню недели объединяет события из разных календарных дат. Такой отчёт описывает типичную нагрузку на сегмент времени, а не отдельный календарный период. При необходимости добавь в зерно дату."
  ],"SELECT EXTRACT(ISODOW FROM ordered_at)::int AS weekday,\n       COUNT(*) AS orders_count\nFROM orders\nGROUP BY EXTRACT(ISODOW FROM ordered_at)::int\nORDER BY weekday;",
  "Какой номер дня недели вернёт EXTRACT(ISODOW ...) для воскресенья?",["0","1","7"],2,"ISODOW использует ISO-нумерацию: от понедельника 1 до воскресенья 7.",[
    T("date-7","Нагрузка по дням недели","Рассчитай число оформленных заказов по дням недели ISO. Верни номер дня weekday и количество orders_count, по порядку от понедельника.","SELECT EXTRACT(ISODOW FROM ordered_at)::int AS weekday,COUNT(*) AS orders_count FROM orders GROUP BY EXTRACT(ISODOW FROM ordered_at)::int ORDER BY weekday;",true),
    T("date-8","Часы оформления","Составь отчёт по часам суток, когда оформляются заказы. Нужны hour и orders_count, час по возрастанию.","SELECT EXTRACT(HOUR FROM ordered_at)::int AS hour,COUNT(*) AS orders_count FROM orders GROUP BY EXTRACT(HOUR FROM ordered_at)::int ORDER BY hour;",true),
    T("date-9","Месячный объём","Посчитай количество заказов по месяцам. Покажи первый день месяца month и orders_count, по возрастанию месяца.","SELECT DATE_TRUNC('month',ordered_at)::date AS month,COUNT(*) AS orders_count FROM orders GROUP BY DATE_TRUNC('month',ordered_at)::date ORDER BY month;",true)
  ],"EXTRACT(HOUR ...) без фильтра по дате совмещает несколько дней в один часовой сегмент. Этот показатель подходит для оценки нагрузки по часам, но не для отчёта об объёме за конкретный день."),
  L("date-interval","INTERVAL: расчёт плановых сроков","Прибавить 90 минут и перейти к следующему месяцу — не одно и то же.",[
    "INTERVAL задаёт длительности и календарные смещения. ordered_at + INTERVAL '90 minutes' создаёт прогнозный момент. Прибавление INTERVAL '1 month' учитывает разную длину месяцев и не равно 30 дням.",
    "Когда требуется измерить SLA или время доставки, важно выбрать события начала и конца. В учебной таблице есть время оформления, но пока нет момента фактической доставки: поэтому мы строим плановые сроки, а не изображаем неизвестную длительность доставки."
  ],"SELECT order_id, ordered_at + INTERVAL '2 days' AS deadline\nFROM orders\nWHERE status='in_transit';",
  "Можно ли по одной отметке ordered_at посчитать фактическое время доставки?",["Да, вычесть два часа","Нет, для длительности нужен второй момент события","Да, если заказ delivered"],1,"Без даты фактического окончания доставки нельзя честно вычислить её длительность.",[
    T("date-10","Срок ожидания","Для каждого заказа в пути рассчитай плановый срок через два дня после оформления. Нужны номер и deadline.","SELECT order_id,ordered_at + INTERVAL '2 days' AS deadline FROM orders WHERE status='in_transit';"),
    T("date-11","Плановый выезд","Для каждого доставленного заказа покажи номер и контрольный момент eta через 90 минут после оформления.","SELECT order_id,ordered_at + INTERVAL '90 minutes' AS eta FROM orders WHERE status='delivered';"),
    T("date-12","Историческая выгрузка","Подготовь номера заказов, оформленных строго раньше полудня 5 апреля 2026 года.","SELECT order_id FROM orders WHERE ordered_at < TIMESTAMP '2026-04-05 12:00';")
  ],"В SQL-выражении TIMESTAMP - TIMESTAMP получается интервал, а TIMESTAMP + INTERVAL — временная метка. Не подменяй неизвестные события вымышленными значениями."),
  L("date-calendar","generate_series: дни без заказов","Отсутствующая строка не равна нулю: календарь нужно построить отдельно.",[
    "GROUP BY по фактам пропускает даты без событий. generate_series позволяет создать непрерывный список дней. Если присоединить к нему заказы через LEFT JOIN, каждый календарный день сохранится независимо от наличия заказов.",
    "На календарной сетке нельзя подсчитывать COUNT(*) как количество заказов: у пустого дня остаётся одна строка календаря. Считай COUNT(o.order_id), а отсутствующую сумму заменяй нулём только после осмысленной проверки."
  ],"SELECT calendar.day::date AS day,\n       COUNT(o.order_id) AS orders_count\nFROM generate_series(DATE '2026-04-01', DATE '2026-04-14', INTERVAL '1 day') AS calendar(day)\nLEFT JOIN orders o\n ON o.ordered_at >= calendar.day\n AND o.ordered_at < calendar.day + INTERVAL '1 day'\nGROUP BY calendar.day\nORDER BY day;",
  "Почему после LEFT JOIN календаря с заказами нужно использовать COUNT(o.order_id), а не COUNT(*)?",["COUNT(*) не считает NULL","COUNT(*) посчитает даже пустую строку календаря","COUNT(o.order_id) считает уникальные заказы автоматически"],1,"При отсутствии заказа LEFT JOIN сохраняет строку календаря; COUNT(*) вернёт 1, а COUNT правого ключа — 0.",[
    T("date-13","Полный календарь","Подготовь непрерывный список календарных дат с 1 по 14 апреля 2026 года включительно, даже если заказов не было. Верни один столбец day по возрастанию.","SELECT day::date AS day FROM generate_series(DATE '2026-04-01',DATE '2026-04-14',INTERVAL '1 day') AS calendar(day) ORDER BY day;",true),
    T("date-14","Дни без заказов","За каждый день с 1 по 14 апреля 2026 года покажи дату day и число оформлений orders_count, включая дни с нулём. Отсортируй дни по возрастанию.","SELECT calendar.day::date AS day,COUNT(o.order_id) AS orders_count FROM generate_series(DATE '2026-04-01',DATE '2026-04-14',INTERVAL '1 day') AS calendar(day) LEFT JOIN orders o ON o.ordered_at >= calendar.day AND o.ordered_at < calendar.day + INTERVAL '1 day' GROUP BY calendar.day ORDER BY day;",true),
    T("date-15","Дни без выручки","Подготовь ежедневную выручку доставленных заказов за 1–14 апреля 2026 года включительно. Покажи day и revenue, ноль для дней без доставок, по возрастанию дат.","SELECT calendar.day::date AS day,COALESCE(SUM(o.amount) FILTER(WHERE o.status='delivered'),0) AS revenue FROM generate_series(DATE '2026-04-01',DATE '2026-04-14',INTERVAL '1 day') AS calendar(day) LEFT JOIN orders o ON o.ordered_at >= calendar.day AND o.ordered_at < calendar.day + INTERVAL '1 day' GROUP BY calendar.day ORDER BY day;",true)
  ],"Календарная сетка нужна не ради красоты графика. Если за нулевые дни нет строк, средние значения по дням и сезонные сравнения искажаются: ряд надо явно дополнить.")
 ]),

 M("cte","Многошаговые запросы","CTE, подзапросы, EXISTS и проверяемые конвейеры расчётов.","06",[
  L("subquery","Подзапросы для сравнения","Иногда условие зависит от значения, которое сначала нужно вычислить.",[
    "Скалярный подзапрос может вернуть одно значение, например средний чек. С ним сравнивают каждую строку исходной таблицы.",
    "Подзапрос внутри WHERE не заменяет осмысленный бизнес-критерий. Сначала уточни, среднее должно быть по всей компании или по каждому магазину."
  ],"SELECT order_id,amount FROM orders\nWHERE amount>(SELECT AVG(amount) FROM orders);","Что должен вернуть скалярный подзапрос?",["Не более одного значения","Ровно тысячу строк","Только названия колонок"],0,"Скалярный подзапрос используется как одиночное выражение; несколько строк дают ошибку.",[
    T("cte-1","Заказы выше среднего","Подготовь номера и суммы заказов дороже среднего чека по всей компании.","SELECT order_id,amount FROM orders WHERE amount>(SELECT AVG(amount) FROM orders);"),
    T("cte-2","Самый большой чек","Найди номера заказов с максимальной суммой. Если максимальных заказов несколько, покажи все.","SELECT order_id FROM orders WHERE amount=(SELECT MAX(amount) FROM orders);")
  ],"Подзапрос может вернуть NULL, если данных нет; затем сравнение с NULL также станет UNKNOWN. Такие случаи особенно важны в отчётах по небольшим сегментам."),
  L("exists","EXISTS и зависимые выборки","Проверяем наличие связанных событий без раздувания строк.",[
    "EXISTS возвращает TRUE, когда подзапрос находит хоть одну подходящую строку. Внутри него обычно не важно, какие поля выбраны — принято писать SELECT 1.",
    "Корреляция означает, что подзапрос использует значение внешней строки, например идентификатор конкретного клиента."
  ],"SELECT c.customer_name\nFROM customers c\nWHERE EXISTS (\n SELECT 1 FROM orders o WHERE o.customer_id=c.customer_id\n);","Нужно ли EXISTS считать все совпавшие заказы?",["Да, иначе некорректно","Нет, достаточно факта существования","Только доставленные"],1,"EXISTS проверяет наличие хотя бы одной подходящей записи.",[
    T("cte-3","Активные клиенты","Назови клиентов, которые хотя бы раз оформляли заказ.","SELECT c.customer_name FROM customers c WHERE EXISTS(SELECT 1 FROM orders o WHERE o.customer_id=c.customer_id);"),
    T("cte-4","Курьеры с доставками","Назови курьеров, у которых есть хотя бы один доставленный заказ.","SELECT c.courier_name FROM couriers c WHERE EXISTS(SELECT 1 FROM orders o WHERE o.courier_id=c.courier_id AND o.status='delivered');")
  ],"EXISTS и INNER JOIN — не всегда взаимозаменяемые формы: JOIN может дублировать имена клиентов по числу заказов, EXISTS сохраняет одну строку на клиента."),
  L("with","WITH: собираем отчёт этапами","Читаемый SQL начинается с разбиения сложной задачи на понятные части.",[
    "CTE через WITH задаёт временное имя для результата внутреннего SELECT. Сначала выбираем факты по бизнес-правилу, затем агрегируем, потом сортируем.",
    "CTE не гарантирует, что запрос выполняется быстрее. Главная его роль здесь — выразить этапы расчёта и позволить отдельно проверять их зерно и контрольные суммы."
  ],"WITH delivered AS (\n SELECT * FROM orders WHERE status='delivered'\n)\nSELECT store_id,SUM(amount) AS revenue\nFROM delivered GROUP BY store_id;","Создаёт ли WITH постоянную таблицу в базе?",["Да","Нет, это именованный этап запроса","Только если написать ORDER BY"],1,"CTE существует только во время выполнения внешнего оператора.",[
    T("cte-5","Выручка доставки","Рассчитай сумму доставленных заказов по каждому магазину: идентификатор и показатель revenue.","WITH delivered AS (SELECT store_id,amount FROM orders WHERE status='delivered') SELECT store_id,SUM(amount) AS revenue FROM delivered GROUP BY store_id;"),
    T("cte-6","Повторные покупатели","Найди идентификаторы покупателей, оформивших более одного заказа.","WITH totals AS (SELECT customer_id,COUNT(*) AS cnt FROM orders GROUP BY customer_id) SELECT customer_id FROM totals WHERE cnt>1;"),
    T("cte-7","Средние суммы по статусам","Подготовь среднюю сумму заказа avg_amount для каждого статуса.","WITH base AS (SELECT status,amount FROM orders) SELECT status,AVG(amount) AS avg_amount FROM base GROUP BY status;")
  ],"Тестируй этапы: у результата filtered_orders должно оставаться зерно заказа, у revenue_by_store — зерно магазина. Ошибка на первом шаге не исправится на последнем."),
  L("conditional","Несколько уровней агрегации","Как сделать итог по группам, не потеряв смысл промежуточных показателей.",[
    "Иногда бизнес хочет средний показатель по магазинам, а не средний по отдельным заказам. Тогда сначала вычисляется показатель для каждого магазина, затем агрегируются полученные группы.",
    "Среднее средних может отличаться от общего среднего по заказам: магазины имеют разное количество заказов. Уровень агрегации — часть определения метрики."
  ],"WITH store_totals AS (\n SELECT store_id, SUM(amount) AS total_amount\n FROM orders GROUP BY store_id\n)\nSELECT AVG(total_amount) AS avg_store_turnover\nFROM store_totals;","Почему среднее средних по магазинам не всегда равно среднему чеку по всем заказам?",["Разные магазины имеют разное число заказов","Потому что SQL округляет до нуля","Такого различия не бывает"],0,"Среднее по магазинам даёт каждому магазину одинаковый вес, а среднее по заказам — каждому заказу.",[
    T("cte-8","Средний оборот магазина","Посчитай среднюю сумму всех заказов на магазин. Назови результат avg_store_turnover.","WITH t AS (SELECT store_id,SUM(amount) AS total_amount FROM orders GROUP BY store_id) SELECT AVG(total_amount) AS avg_store_turnover FROM t;"),
    T("cte-9","Магазины выше среднего оборота","Найди идентификаторы магазинов, общий оборот заказов которых выше среднего оборота на магазин.","WITH t AS (SELECT store_id,SUM(amount) AS total_amount FROM orders GROUP BY store_id) SELECT store_id FROM t WHERE total_amount>(SELECT AVG(total_amount) FROM t);")
  ],"Сначала уточни, чего именно требуется «среднее»: по фактам, по дням, по магазинам или по клиентам. Это четыре разных бизнес-показателя.")
 ]),
 M("windows","Оконные функции","Ранжирование, предыдущие события и накопительные показатели.","07",[
  L("row-number","ROW_NUMBER и упорядочивание","Нумеруем строки внутри групп, не теряя детализацию.",[
    "Оконная функция с OVER вычисляет дополнительное значение для строки, но не сворачивает исходные строки, как GROUP BY.",
    "PARTITION BY делит строки на независимые группы, ORDER BY внутри окна устанавливает порядок. Чтобы нумерация была воспроизводимой при равных значениях, добавь уникальный идентификатор."
  ],"SELECT order_id,store_id,\n ROW_NUMBER() OVER(PARTITION BY store_id ORDER BY amount DESC,order_id) AS rn\nFROM orders;","Что делает PARTITION BY в ROW_NUMBER?",["Делит строки на отдельные нумеруемые группы","Удаляет повторы","Ограничивает количество строк"],0,"Нумерация начинается заново внутри каждой группы.",[
    T("win-1","Нумерация заказов","Для каждого заказа покажи номер, идентификатор магазина и позицию rn по убыванию суммы внутри магазина. При равной сумме первым должен быть меньший номер заказа.","SELECT order_id,store_id,ROW_NUMBER() OVER(PARTITION BY store_id ORDER BY amount DESC,order_id) AS rn FROM orders;"),
    T("win-2","Порядок клиентов","Для каждого клиента покажи идентификатор и позицию rn при сортировке по дате регистрации, затем по идентификатору.","SELECT customer_id,ROW_NUMBER() OVER(ORDER BY registered_at,customer_id) AS rn FROM customers;")
  ],"ROW_NUMBER не гарантирует одинаковую нумерацию строк с одинаковыми ключами ORDER BY. Без дополнительного tie-breaker итог top-N может быть непредсказуемым."),
  L("rank","RANK и DENSE_RANK","Равные суммы должны получать одинаковые места, но что делать с пропусками?",[
    "RANK присваивает одинаковый ранг равным значениям и пропускает последующие номера. DENSE_RANK не создаёт таких пропусков. ROW_NUMBER всегда создаёт уникальные номера.",
    "В рейтинге магазинов нужно решить, включать ли всех разделивших последнее проходное место. Разные функции отвечают на разные бизнес-требования."
  ],"SELECT order_id,amount,\n DENSE_RANK() OVER(ORDER BY amount DESC) AS position\nFROM orders;","Для сумм 100,100,80 какие ранги даст RANK?",["1,2,3","1,1,3","1,1,2"],1,"После двух строк на первом месте RANK пропускает вторую позицию.",[
    T("win-3","Ранг чеков","Покажи номер, сумму заказа и ранг rnk от самой большой суммы без пропуска позиций при равенстве.","SELECT order_id,amount,DENSE_RANK() OVER(ORDER BY amount DESC) AS rnk FROM orders;"),
    T("win-4","Места заказов","Покажи номер, сумму заказа и ранг place по убыванию суммы с пропуском номеров после ничьей.","SELECT order_id,amount,RANK() OVER(ORDER BY amount DESC) AS place FROM orders;")
  ],"Одинаковые суммы не означают одинаковые заказы. Ранжирование по сумме допускает ничью, но ROW_NUMBER требует отдельной детерминированной сортировки."),
  L("lag","LAG: что было до этого","Переходим от одного события к последовательности событий.",[
    "LAG обращается к значению в предыдущей строке, определённой ORDER BY окна. Он возвращает NULL, если предыдущей строки нет.",
    "Для анализа покупательской истории важно добавить PARTITION BY customer_id. Иначе предыдущим окажется заказ другого покупателя."
  ],"SELECT customer_id,order_id,amount,\n LAG(amount) OVER(PARTITION BY customer_id ORDER BY ordered_at,order_id) AS previous_amount\nFROM orders;","Что вернёт LAG для первой строки каждой группы?",["0","NULL, если не указано другое значение по умолчанию","Значение последней строки"],1,"У первой строки нет предыдущей записи внутри окна.",[
    T("win-5","Предыдущий чек","По каждому заказу покажи идентификатор покупателя, номер заказа и сумму предыдущего заказа previous_amount того же покупателя. Порядок событий — время, затем номер заказа.","SELECT customer_id,order_id,LAG(amount) OVER(PARTITION BY customer_id ORDER BY ordered_at,order_id) AS previous_amount FROM orders;"),
    T("win-6","Предыдущий статус","Для каждого заказа покажи покупателя, номер и предыдущий статус previous_status по истории его заказов.","SELECT customer_id,order_id,LAG(status) OVER(PARTITION BY customer_id ORDER BY ordered_at,order_id) AS previous_status FROM orders;")
  ],"Без ORDER BY внутри OVER понятие «предыдущий» не имеет делового смысла. При совпадающих временных метках нужен дополнительный уникальный ключ."),
  L("running","Накопительная сумма","Считаем итог нарастающим результатом, сохраняя каждое событие.",[
    "SUM(...) OVER с ORDER BY и рамкой ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW считает все строки с начала группы по текущую.",
    "Если убрать рамку, поведение при одинаковых ключах сортировки может отличаться: рамка RANGE по умолчанию способна включать сразу несколько одинаковых значений. Формулируй это явно."
  ],"SELECT order_id,amount,\n SUM(amount) OVER(ORDER BY ordered_at,order_id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_total\nFROM orders;","Что происходит с количеством строк при SUM(...) OVER?",["Все строки исчезают","Количество исходных строк сохраняется","Остаётся одна строка на группу"],1,"Оконные вычисления добавляют показатели к отдельным исходным строкам.",[
    T("win-7","Накопленный оборот","Для каждого заказа покажи его номер и сумму running_total накопленным итогом по времени оформления и номеру.","SELECT order_id,SUM(amount) OVER(ORDER BY ordered_at,order_id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_total FROM orders;"),
    T("win-8","Накопленный оборот магазина","Для каждого заказа покажи номер, идентификатор магазина и сумму running_store_total заказов этого магазина нарастающим итогом по времени и номеру.","SELECT order_id,store_id,SUM(amount) OVER(PARTITION BY store_id ORDER BY ordered_at,order_id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_store_total FROM orders;"),
    T("win-9","Нумерация истории","Покажи покупателя, номер заказа и порядковый номер покупки purchase_no внутри истории каждого клиента по времени и номеру заказа.","SELECT customer_id,order_id,ROW_NUMBER() OVER(PARTITION BY customer_id ORDER BY ordered_at,order_id) AS purchase_no FROM orders;")
  ],"Накопительная сумма по сырым заказам и накопительная сумма по дням — разные таблицы результатов. Для дневной динамики сначала агрегируй заказы по дням, затем применяй окно.")
 ]) ,
 M("audit","Сложные JOIN и качество данных","Зерно, две связи один-ко-многим, сверка денег и расследование ошибочных отчётов.","08",[
  L("audit-grain","Предсказываем число строк после JOIN","Даже правильный SQL может превратить один заказ в несколько строк.",[
   "В orders одна строка означает один заказ. В order_items — товарную позицию, а в order_events — отдельное изменение состояния заказа. Если соединить orders с историей событий, каждая строка заказа повторится столько раз, сколько за ним записано событий. Сначала зафиксируй зерно каждого источника, затем предскажи число совпадений.",
   "COUNT(*) после соединения считает строки результата, а COUNT(DISTINCT order_id) — уникальные заказы. Это разные метрики. DISTINCT полезен для проверки кардинальности, но не исправляет автоматом завышенный SUM денег. Если в истории событий у заказа нет строк, INNER JOIN удалит такой заказ, а LEFT JOIN сохранит."
  ],"SELECT COUNT(*) AS joined_rows,\n       COUNT(DISTINCT o.order_id) AS orders_count\nFROM orders o\nJOIN order_events e ON e.order_id=o.order_id;",
  "У одного заказа две товарные позиции и три события. Сколько строк даст соединение обоих наборов деталей по заказу?",["Две","Три","Шесть"],2,"Каждая позиция сочетается с каждым событием: 2 × 3 = 6. Это смена зерна, а не шесть заказов.",[
   T("audit-1","Реальный объём журнала","Отдел контроля сравнивает объём журнала и число уникальных заказов, представленных в нём. Верни показатели event_rows и orders_with_events одним результатом.","SELECT COUNT(*) AS event_rows,COUNT(DISTINCT order_id) AS orders_with_events FROM order_events;"),
   T("audit-2","Сложная история","Найди номера заказов с тремя и более событиями в истории и количество таких событий events_count.","SELECT o.order_id,COUNT(e.event_id) AS events_count FROM orders o LEFT JOIN order_events e ON e.order_id=o.order_id GROUP BY o.order_id HAVING COUNT(e.event_id)>=3;"),
   T("audit-3","Покрытие операционного журнала","Посчитай количество заказов без единой записи в журнале. Назови метрику missing_history.","SELECT COUNT(*) AS missing_history FROM orders o WHERE NOT EXISTS(SELECT 1 FROM order_events e WHERE e.order_id=o.order_id);")
  ],"Проверка JOIN начинается с вопроса «одна строка сейчас что означает?». Если ожидаешь один заказ, но получил строку на каждое событие, не суммируй стоимость заказа до возвращения на нужный уровень."),
  L("audit-preaggregate","Две связи один-ко-многим: устраняем fan-out","Товарные позиции и события независимо размножают заказы.",[
   "У заказа может быть две позиции и два события. Если одновременно соединить оба набора деталей, получится четыре строки — произведение совпадений. COUNT(item_id) и COUNT(event_id) покажут четыре вместо двух, а SUM(amount) повторит деньги четыре раза.",
   "Надёжный способ — сначала агрегировать каждую таблицу деталей до одной строки на order_id, затем присоединить сводки к orders. После соединения снова проверь уникальность заказа и суммы. В простых задачах COUNT(DISTINCT id) исправляет подсчёт записей, но не спасает SUM(amount)."
  ],"WITH items AS (\n SELECT order_id,COUNT(*) AS positions FROM order_items GROUP BY order_id\n), events AS (\n SELECT order_id,COUNT(*) AS updates_count FROM order_events GROUP BY order_id\n)\nSELECT o.order_id,COALESCE(i.positions,0) AS positions,\n       COALESCE(e.updates_count,0) AS updates_count\nFROM orders o\nLEFT JOIN items i ON i.order_id=o.order_id\nLEFT JOIN events e ON e.order_id=o.order_id;",
  "Почему SUM(DISTINCT o.amount) после такого JOIN не годится для подсчёта выручки?",["Суммы двух разных заказов могут совпасть","Потому что SUM не допускает DISTINCT","DISTINCT учитывает только NULL"],0,"DISTINCT по сумме устраняет одинаковые значения, а не повторение конкретных заказов. Нужна агрегация по бизнес-ключу.",[
   T("audit-4","Два независимых счётчика","Для каждого заказа одновременно покажи номер, число товарных позиций positions и число исторических событий updates_count. Заказы без записей должны получить нули, а не исчезнуть.","WITH i AS(SELECT order_id,COUNT(*) AS positions FROM order_items GROUP BY order_id),e AS(SELECT order_id,COUNT(*) AS updates_count FROM order_events GROUP BY order_id) SELECT o.order_id,COALESCE(i.positions,0) AS positions,COALESCE(e.updates_count,0) AS updates_count FROM orders o LEFT JOIN i ON i.order_id=o.order_id LEFT JOIN e ON e.order_id=o.order_id;"),
   T("audit-5","Выручка и нагрузка на журнал","По каждому магазину, включая пустые, рассчитай выручку только доставленных заказов revenue и число всех записей истории событий updates_count. Не допускай размножения сумм.","WITH r AS(SELECT store_id,COALESCE(SUM(amount) FILTER(WHERE status='delivered'),0) AS revenue FROM orders GROUP BY store_id),h AS(SELECT o.store_id,COUNT(e.event_id) AS updates_count FROM orders o LEFT JOIN order_events e ON e.order_id=o.order_id GROUP BY o.store_id) SELECT s.store_id,COALESCE(r.revenue,0) AS revenue,COALESCE(h.updates_count,0) AS updates_count FROM stores s LEFT JOIN r ON r.store_id=s.store_id LEFT JOIN h ON h.store_id=s.store_id;"),
   T("audit-6","История клиентских покупок","Для каждого клиента с заказами покажи идентификатор, общий оборот total_amount и количество заказанных товарных позиций positions. Деньги учитывай ровно один раз на заказ.","WITH i AS(SELECT order_id,COUNT(*) AS positions FROM order_items GROUP BY order_id) SELECT o.customer_id,SUM(o.amount) AS total_amount,COALESCE(SUM(i.positions),0) AS positions FROM orders o LEFT JOIN i ON i.order_id=o.order_id GROUP BY o.customer_id;")
  ],"Техническая защита от fan-out: вычисляй метрики на их собственном зерне. Сумма заказа хранится на уровне заказа, количество позиций — на уровне позиции, число событий — на уровне события."),
  L("audit-reconciliation","Сверяем сумму заказа с товарными позициями","Два независимых источника могут противоречить друг другу.",[
   "orders.amount — сумма в заголовке заказа. order_items хранит количество и цену каждой позиции. Для проверки можно вычислить SUM(quantity * unit_price) по order_id и сопоставить её с суммой заголовка. Это две независимые финансовые величины, а не две копии одного столбца.",
   "Заказ без позиций не должен молча пропасть: LEFT JOIN сохранит его. COALESCE поможет представить отсутствие позиций нулём, но в реальной системе важно отличать отсутствие записи от настоящей нулевой суммы. В изменённом датасете есть дополнительная расходимость: проверка должна работать и после обновления данных."
  ],"WITH item_totals AS (\n SELECT order_id,SUM(quantity*unit_price) AS items_total\n FROM order_items GROUP BY order_id\n)\nSELECT o.order_id,o.amount AS header_total,\n       COALESCE(i.items_total,0) AS items_total\nFROM orders o LEFT JOIN item_totals i ON i.order_id=o.order_id;",
  "Почему при финансовой сверке важно сохранять заказы без позиций?",["Чтобы не потерять самую важную аномалию","Потому что INNER JOIN возвращает их как NULL","Потому что SUM всегда возвращает ноль"],0,"INNER JOIN удалил бы заказы без товарных позиций, спрятав проблему данных.",[
   T("audit-7","Контроль товарного чека","Для каждого заказа покажи номер, сумму заголовка header_total и итог по товарным позициям items_total. У заказов без позиций итог позиций должен быть нулём.","WITH i AS(SELECT order_id,SUM(quantity*unit_price) AS items_total FROM order_items GROUP BY order_id) SELECT o.order_id,o.amount AS header_total,COALESCE(i.items_total,0) AS items_total FROM orders o LEFT JOIN i ON i.order_id=o.order_id;"),
   T("audit-8","Расхождения в учёте","Найди номера заказов, где сумма заголовка и стоимость позиций не совпадают. Верни номер и разницу difference (сумма заголовка минус сумма позиций).","WITH i AS(SELECT order_id,SUM(quantity*unit_price) AS items_total FROM order_items GROUP BY order_id) SELECT o.order_id,o.amount-COALESCE(i.items_total,0) AS difference FROM orders o LEFT JOIN i ON i.order_id=o.order_id WHERE o.amount IS DISTINCT FROM COALESCE(i.items_total,0);"),
   T("audit-9","Проверка оборота магазинов","По каждому магазину с заказами покажи идентификатор, общий оборот заказов order_total и сумму их товарных позиций items_total. Учитывай товары каждого заказа один раз.","WITH i AS(SELECT order_id,SUM(quantity*unit_price) AS items_total FROM order_items GROUP BY order_id) SELECT o.store_id,SUM(o.amount) AS order_total,COALESCE(SUM(i.items_total),0) AS items_total FROM orders o LEFT JOIN i ON i.order_id=o.order_id GROUP BY o.store_id;")
  ],"Сумма заказа может отличаться от цены позиций по законной причине — скидки, доставка, возвраты. В нашем учебном примере она служит контрольной величиной, но в реальном бизнесе сначала согласуют правило сверки."),
  L("audit-latest-event","Актуальное состояние из истории событий","Нельзя брать первую или любую запись в журнале за последнюю.",[
   "В order_events у заказа несколько изменений состояния. Чтобы взять самое новое, нужна сортировка по event_at и дополнительный уникальный event_id на случай одинакового времени. ROW_NUMBER() OVER(PARTITION BY order_id ORDER BY event_at DESC,event_id DESC) присвоит последнему событию rn=1.",
   "Когда ты присоединяешь последнюю запись обратно к orders, сохраняй все заказы и сравни фактический статус с последним событием. В тестовом наборе есть заказ с неполной историей, а в альтернативном — дополнительное несоответствие, которое обычный JOIN может спрятать."
  ],"WITH ranked AS (\n SELECT order_id,event_type,\n ROW_NUMBER() OVER(PARTITION BY order_id ORDER BY event_at DESC,event_id DESC) AS rn\n FROM order_events\n)\nSELECT o.order_id,r.event_type AS last_event_type\nFROM orders o LEFT JOIN ranked r ON r.order_id=o.order_id AND r.rn=1;",
  "Почему недостаточно сортировать по event_at, если две записи имеют одинаковое время?",["Нужен второй стабильный критерий, например event_id","PostgreSQL запрещает одинаковое время","Можно использовать DISTINCT без ORDER BY"],0,"Без уникального дополнительного ключа выбор последнего события может быть неопределённым.",[
   T("audit-10","Последнее событие каждого заказа","Составь список всех номеров заказов и типов их последних событий last_event_type. Сохраняй даже заказы, в которых журнал пуст.","WITH r AS(SELECT order_id,event_type,ROW_NUMBER() OVER(PARTITION BY order_id ORDER BY event_at DESC,event_id DESC) AS rn FROM order_events) SELECT o.order_id,r.event_type AS last_event_type FROM orders o LEFT JOIN r ON r.order_id=o.order_id AND r.rn=1;"),
   T("audit-11","Найдены противоречия статусов","Выведи номера заказов, у которых статус в карточке заказа не совпадает с последним событием журнала. Отсутствующая история тоже считается расхождением.","WITH r AS(SELECT order_id,event_type,ROW_NUMBER() OVER(PARTITION BY order_id ORDER BY event_at DESC,event_id DESC) AS rn FROM order_events) SELECT o.order_id FROM orders o LEFT JOIN r ON r.order_id=o.order_id AND r.rn=1 WHERE o.status IS DISTINCT FROM r.event_type;"),
   T("audit-12","Последнее обновление","Для каждого заказа покажи номер и момент последнего события last_update. Для заказов без истории оставь NULL.","SELECT o.order_id,MAX(e.event_at) AS last_update FROM orders o LEFT JOIN order_events e ON e.order_id=o.order_id GROUP BY o.order_id;")
  ],"Функция MAX(event_at) правильно найдёт момент, но сама не вернёт тип именно этого события без дополнительной логики. Для полного события безопаснее выбрать одну строку по детерминированному рангу."),
  L("audit-quality","Дубликаты и пропущенные операционные события","Запрос может быть верным, а данные — нет.",[
   "У события event_id уникален, но сочетание (order_id,event_type) может повторяться. Две записи assigned для заказа — сигнал на расследование, не автоматическое доказательство ошибки. Важно различать технический дубликат и повторную законную попытку операции.",
   "Другой класс проблем — пробелы в истории: у заказа нет ни одного события либо последняя запись не соответствует текущему статусу. Для контроля нужны независимые проверки, которые возвращают конкретные аномальные объекты, а не только общую сумму."
  ],"SELECT order_id,event_type,COUNT(*) AS occurrences\nFROM order_events\nGROUP BY order_id,event_type\nHAVING COUNT(*)>1;",
  "Если в журнале два события с одинаковым event_type для одного заказа, можно ли без дополнительных сведений автоматически удалить одно?",["Да, всегда","Нет: это повод для проверки, но повтор мог быть легитимным","Да, если сумма заказа положительная"],1,"Повтор типа события может отражать повторную попытку обработки. Удаление требует бизнес-правил и признаков реального дубликата.",[
   T("audit-13","Повторные переходы состояния","Найди сочетания номера заказа и типа события, которые встречаются в журнале больше одного раза. Покажи order_id, event_type и число occurrences.","SELECT order_id,event_type,COUNT(*) AS occurrences FROM order_events GROUP BY order_id,event_type HAVING COUNT(*)>1;"),
   T("audit-14","Заказы без журнала","Выведи номера заказов, для которых в журнале ещё нет ни одного события.","SELECT o.order_id FROM orders o WHERE NOT EXISTS(SELECT 1 FROM order_events e WHERE e.order_id=o.order_id);"),
   T("audit-15","Доставки без подтверждения","Найди номера заказов со статусом delivered, для которых не зарегистрировано ни одного события delivered.","SELECT o.order_id FROM orders o WHERE o.status='delivered' AND NOT EXISTS(SELECT 1 FROM order_events e WHERE e.order_id=o.order_id AND e.event_type='delivered');")
  ],"Качественный отчёт должен сообщать не только сколько продаж было, но и сколько записей не прошло контрольные правила. У каждого правила должны быть известны ложные срабатывания и допустимые исключения."),
  L("audit-full-join","FULL JOIN: сверка двух независимых сводок","Ключи могут встречаться только в одной из сторон.",[
   "FULL OUTER JOIN сохраняет совпадающие строки и несовпавшие строки обеих сторон. Это помогает сопоставлять независимые сводки: например дни с доставками и дни с отменами. INNER JOIN потерял бы дни, где был только один из этих двух видов событий.",
   "Перед соединением каждая сводка должна иметь одну строку на day. После FULL JOIN общий ключ получаем через COALESCE(left.day,right.day), а отсутствующий счётчик превращаем в ноль. Порядок в итоговом отчёте явно задаём через ORDER BY."
  ],"WITH d AS (\n SELECT ordered_at::date AS day,COUNT(*) AS delivered\n FROM orders WHERE status='delivered' GROUP BY ordered_at::date\n), c AS (\n SELECT ordered_at::date AS day,COUNT(*) AS cancelled\n FROM orders WHERE status='cancelled' GROUP BY ordered_at::date\n)\nSELECT COALESCE(d.day,c.day) AS day,\n       COALESCE(d.delivered,0) AS delivered,\n       COALESCE(c.cancelled,0) AS cancelled\nFROM d FULL JOIN c ON d.day=c.day ORDER BY day;",
  "Что произойдёт с днём, в который были только отменённые заказы, при INNER JOIN сводок доставок и отмен?",["Останется с нулём доставок","Пропадёт из результата","Появится как NULL без даты"],1,"INNER JOIN требует совпадения ключа с обеих сторон. Для сохранения непересекающихся дней нужен FULL OUTER JOIN.",[
   T("audit-16","Сведение ежедневных операций","Составь сводку по дням, когда была хотя бы одна доставка или отмена. Покажи дату day, количество доставок delivered и отмен cancelled, нули для отсутствующей категории, даты по возрастанию.","WITH d AS(SELECT ordered_at::date AS day,COUNT(*) AS delivered FROM orders WHERE status='delivered' GROUP BY ordered_at::date),c AS(SELECT ordered_at::date AS day,COUNT(*) AS cancelled FROM orders WHERE status='cancelled' GROUP BY ordered_at::date) SELECT COALESCE(d.day,c.day) AS day,COALESCE(d.delivered,0) AS delivered,COALESCE(c.cancelled,0) AS cancelled FROM d FULL JOIN c ON d.day=c.day ORDER BY day;",true),
   T("audit-17","Дни без единой доставки","Найди дни, когда были отмены, но не было ни одной доставки. Верни day по возрастанию.","WITH d AS(SELECT DISTINCT ordered_at::date AS day FROM orders WHERE status='delivered'),c AS(SELECT DISTINCT ordered_at::date AS day FROM orders WHERE status='cancelled') SELECT c.day FROM c FULL JOIN d ON d.day=c.day WHERE d.day IS NULL ORDER BY c.day;",true),
   T("audit-18","Баланс по магазинам","По каждому магазину, у которого были доставки или отмены, покажи store_id, доставленную выручку revenue и общую сумму отмен cancelled_amount. Отсутствующие показатели замени нулём.","WITH d AS(SELECT store_id,SUM(amount) AS revenue FROM orders WHERE status='delivered' GROUP BY store_id),c AS(SELECT store_id,SUM(amount) AS cancelled_amount FROM orders WHERE status='cancelled' GROUP BY store_id) SELECT COALESCE(d.store_id,c.store_id) AS store_id,COALESCE(d.revenue,0) AS revenue,COALESCE(c.cancelled_amount,0) AS cancelled_amount FROM d FULL JOIN c ON d.store_id=c.store_id;")
  ],"FULL JOIN полезен для сверки, но не должен подменять календарную сетку. Он покажет только ключи, встречающиеся хотя бы в одном источнике; для полного календаря по-прежнему нужен generate_series.")
 ]),
 M("product","Продуктовая аналитика","События пользователей, конверсии, когорты, выручка и проверки качества.","09",[
  L("product-events","События и уникальные пользователи","У одного пользователя могут быть десятки событий, но сам пользователь один.",[
    "Новая учебная база — мобильный сервис. В app_users одна строка соответствует пользователю, в user_events — одному событию: просмотр, добавление в корзину или покупка. Сначала зафиксируй, что именно считаешь, иначе COUNT(*) из таблицы событий ошибочно назовёшь числом пользователей.",
    "DAU — число уникальных активных пользователей за день при заранее определённом событии активности. В этом уроке активностью считается любое событие. COUNT(DISTINCT user_id) позволяет не считать многократные действия одного человека несколько раз."
  ],"SELECT event_at::date AS day,\n COUNT(DISTINCT user_id) AS active_users\nFROM user_events\nGROUP BY event_at::date\nORDER BY day;",
  "Почему COUNT(*) из user_events не равен числу активных пользователей?",["Потому что в PostgreSQL COUNT не работает с событиями","Один пользователь может совершить много событий","Потому что время хранится текстом"],1,"Количество событий и количество уникальных людей — разные бизнес-показатели.",[
    T("product-1","Все события","Посчитай общее количество записанных событий продукта. Назови результат events_count.","SELECT COUNT(*) AS events_count FROM user_events;"),
    T("product-2","Активная аудитория","Определи число разных пользователей, которые совершили хотя бы одно событие за весь доступный период. Назови результат active_users.","SELECT COUNT(DISTINCT user_id) AS active_users FROM user_events;"),
    T("product-3","Дневная активность","По каждому дню, когда были события, верни дату day и число уникальных активных пользователей active_users, по возрастанию даты.","SELECT event_at::date AS day,COUNT(DISTINCT user_id) AS active_users FROM user_events GROUP BY event_at::date ORDER BY day;",true)
  ],"Одна строка user_events — событие, а не человек. Случайный JOIN событий и покупок может размножить обе таблицы: изучай зерно источника до вычисления любого KPI."),
  L("product-funnel","Воронка: кто дошёл до покупки","От количества кликов переходим к поведению людей.",[
    "У продукта есть события view, add_to_cart и purchase. Простая «охватная» воронка показывает, сколько уникальных пользователей когда-либо совершали каждый тип события. Это ещё не строгая последовательная воронка: она не требует, чтобы действие произошло после предыдущего шага и в определённое окно времени.",
    "EXISTS помогает отвечать на вопросы об участии: был ли у пользователя хотя бы один просмотр, покупка, добавление в корзину. Такой подход сохраняет одну строку на пользователя, даже если события повторяются."
  ],"SELECT event_type,\n COUNT(DISTINCT user_id) AS users_count\nFROM user_events\nGROUP BY event_type;",
  "Можно ли назвать COUNT(DISTINCT user_id) по каждому типу события полноценной последовательной воронкой?",["Да, порядок событий не важен","Нет, не проверено время и порядок переходов","Да, если событий больше десяти"],1,"Охват шагов и последовательная воронка — разные понятия. Для строгой воронки понадобится проверить порядок событий.",[
    T("product-4","Охват шагов продукта","Для каждого типа события посчитай количество различных пользователей users_count. Покажи название типа и значение.","SELECT event_type,COUNT(DISTINCT user_id) AS users_count FROM user_events GROUP BY event_type;"),
    T("product-5","Первый платёж","Подготовь идентификаторы пользователей, совершивших хотя бы одну покупку.","SELECT DISTINCT user_id FROM user_events WHERE event_type='purchase';"),
    T("product-6","Начали, но не купили","Найди идентификаторы пользователей, которые хотя бы раз просматривали товары, но ни разу не совершали покупку.","SELECT u.user_id FROM app_users u WHERE EXISTS(SELECT 1 FROM user_events e WHERE e.user_id=u.user_id AND e.event_type='view') AND NOT EXISTS(SELECT 1 FROM user_events e WHERE e.user_id=u.user_id AND e.event_type='purchase');")
  ],"Не смешивай просмотр, пользователя, сессию и покупку в одном знаменателе. Метрика конверсии корректна только тогда, когда числитель и знаменатель относятся к одной единице анализа."),
  L("product-conversion","Конверсия и правильный знаменатель","Процент может быть вычислен математически правильно и всё равно говорить не то.",[
    "Определим конверсию зарегистрированных в платящих: число уникальных пользователей с хотя бы одной покупкой, разделённое на число зарегистрированных пользователей за доступный период. Считать нужно людей, а не количество событий purchase.",
    "При группировке по рекламному каналу LEFT JOIN сохраняет зарегистрированных людей без событий. COUNT(DISTINCT u.user_id) служит знаменателем; FILTER по покупкам — числителем. Используй NULLIF для защиты деления на ноль и дробную арифметику, чтобы не потерять проценты."
  ],"SELECT u.channel,\n COUNT(DISTINCT u.user_id) AS signups,\n COUNT(DISTINCT u.user_id) FILTER(WHERE e.event_type='purchase') AS payers\nFROM app_users u\nLEFT JOIN user_events e ON e.user_id=u.user_id\nGROUP BY u.channel;",
  "Почему количество событий purchase нельзя напрямую делить на число зарегистрированных людей?",["Одному человеку может принадлежать несколько покупок","Все зарегистрированные обязаны покупать","COUNT(DISTINCT) всегда равен COUNT(*)"],0,"Один покупатель может совершить много платежей, но остаётся одним платящим пользователем.",[
    T("product-7","Покупатели по каналам","Для каждого канала привлечения посчитай зарегистрированных пользователей signups и число уникальных купивших payers. Покажи канал и оба показателя.","SELECT u.channel,COUNT(DISTINCT u.user_id) AS signups,COUNT(DISTINCT u.user_id) FILTER(WHERE e.event_type='purchase') AS payers FROM app_users u LEFT JOIN user_events e ON e.user_id=u.user_id GROUP BY u.channel;"),
    T("product-8","Общая конверсия в покупку","Рассчитай процент зарегистрированных пользователей, которые совершили хотя бы одну покупку. Назови результат purchase_rate_pct, округли до двух знаков после запятой.","SELECT ROUND(100.0*COUNT(DISTINCT u.user_id) FILTER(WHERE e.event_type='purchase')/NULLIF(COUNT(DISTINCT u.user_id),0),2) AS purchase_rate_pct FROM app_users u LEFT JOIN user_events e ON e.user_id=u.user_id;"),
    T("product-9","Конверсия каналов","Для каждого канала привлечения выведи channel и процент зарегистрированных, совершивших хотя бы одну покупку purchase_rate_pct, с округлением до двух десятичных знаков.","SELECT u.channel,ROUND(100.0*COUNT(DISTINCT u.user_id) FILTER(WHERE e.event_type='purchase')/NULLIF(COUNT(DISTINCT u.user_id),0),2) AS purchase_rate_pct FROM app_users u LEFT JOIN user_events e ON e.user_id=u.user_id GROUP BY u.channel;")
  ],"Конверсия зарегистрированных в покупку — метрика за весь период в доступной базе, а не кумулятивный retention или конверсия сессий. Для сравнения каналов дополнительно фиксируй временное окно и зрелость когорт."),
  L("product-cohorts","Когортный анализ и удержание","Сравнивай активность людей, зарегистрированных в одном месяце.",[
    "Когорта — набор пользователей с общим временем старта. Здесь пользователи группируются по месяцу регистрации. В отчёте удержания важна разница между месяцем регистрации и месяцем активности, а не просто активность в каком-либо календарном месяце.",
    "Для Month-1 Retention пользователь должен совершить хотя бы одно событие в следующем календарном месяце после регистрации. В знаменатель входят все пользователи исходной когорты, даже если ни разу не пользовались сервисом после регистрации. Историю неполных когорт следует интерпретировать осторожно."
  ],"SELECT DATE_TRUNC('month',u.signup_date)::date AS cohort_month,\n COUNT(DISTINCT u.user_id) AS cohort_size,\n COUNT(DISTINCT e.user_id) FILTER(\n  WHERE DATE_TRUNC('month',e.event_at)=DATE_TRUNC('month',u.signup_date)+INTERVAL '1 month'\n ) AS retained_m1\nFROM app_users u LEFT JOIN user_events e ON e.user_id=u.user_id\nGROUP BY DATE_TRUNC('month',u.signup_date)::date;",
  "Какой знаменатель нужен для удержания когорты в следующем месяце?",["Количество событий в следующем месяце","Количество уникальных пользователей исходной когорты","Все пользователи, когда-либо покупавшие"],1,"В retention сравнивают вернувшихся пользователей с постоянным размером стартовой когорты.",[
    T("product-10","Размер когорт","Посчитай число зарегистрированных пользователей для каждого месяца регистрации. Покажи начало месяца cohort_month и размер cohort_size.","SELECT DATE_TRUNC('month',signup_date)::date AS cohort_month,COUNT(*) AS cohort_size FROM app_users GROUP BY DATE_TRUNC('month',signup_date)::date;"),
    T("product-11","Месяц активности когорты","Для каждого сочетания месяца регистрации cohort_month и месяца события activity_month рассчитай число различных активных пользователей active_users.","SELECT DATE_TRUNC('month',u.signup_date)::date AS cohort_month,DATE_TRUNC('month',e.event_at)::date AS activity_month,COUNT(DISTINCT e.user_id) AS active_users FROM app_users u JOIN user_events e ON e.user_id=u.user_id GROUP BY DATE_TRUNC('month',u.signup_date)::date,DATE_TRUNC('month',e.event_at)::date;"),
    T("product-12","Month-1 Retention","Для каждой когорты выведи месяц регистрации cohort_month, число участников cohort_size и число активных пользователей в следующем календарном месяце retained_m1. Сохрани когорты с нулём вернувшихся.","SELECT DATE_TRUNC('month',u.signup_date)::date AS cohort_month,COUNT(DISTINCT u.user_id) AS cohort_size,COUNT(DISTINCT e.user_id) FILTER(WHERE DATE_TRUNC('month',e.event_at)=DATE_TRUNC('month',u.signup_date)+INTERVAL '1 month') AS retained_m1 FROM app_users u LEFT JOIN user_events e ON e.user_id=u.user_id GROUP BY DATE_TRUNC('month',u.signup_date)::date;")
  ],"Month-1 Retention считают по людям, не по событиям. Размер когорты нельзя уменьшать до числа пользователей с событиями, иначе показатель удержания искусственно вырастет."),
  L("product-revenue","Выручка и повторные покупки","Различаем платящих людей, платежи и деньги.",[
    "В user_events каждая purchase-строка — одна покупка с суммой amount. Один пользователь может платить несколько раз. Поэтому count событий purchase, count уникальных платящих и sum денежных сумм — три разных показателя.",
    "При соединении app_users с user_events канал можно использовать как сегмент выручки. Не суммируй суммы после дополнительных независимых JOIN один-ко-многим: повторная деталь может раздуть деньги. Для анализа месячной выручки группируй по событию оплаты, а не по месяцу регистрации."
  ],"SELECT u.channel,\n COALESCE(SUM(e.amount) FILTER(WHERE e.event_type='purchase'),0) AS revenue\nFROM app_users u LEFT JOIN user_events e ON e.user_id=u.user_id\nGROUP BY u.channel;",
  "Что измеряет COUNT(DISTINCT user_id) среди событий purchase?",["Число отдельных платежей","Число уникальных платящих пользователей","Общую выручку"],1,"Платящий пользователь может совершить несколько отдельных покупок.",[
    T("product-13","Выручка каналов","Для каждого канала привлечения рассчитай общую сумму покупок revenue. Покажи все каналы, в том числе без платежей (с нулевой суммой).","SELECT u.channel,COALESCE(SUM(e.amount) FILTER(WHERE e.event_type='purchase'),0) AS revenue FROM app_users u LEFT JOIN user_events e ON e.user_id=u.user_id GROUP BY u.channel;"),
    T("product-14","Платежи по месяцам","По каждому месяцу, когда были покупки, покажи первый день месяца month и сумму выручки revenue от платежей этого месяца.","SELECT DATE_TRUNC('month',event_at)::date AS month,SUM(amount) AS revenue FROM user_events WHERE event_type='purchase' GROUP BY DATE_TRUNC('month',event_at)::date;"),
    T("product-15","Повторно платящие","Найди идентификаторы пользователей, совершивших минимум две покупки. Покажи user_id и число покупок purchases_count.","SELECT user_id,COUNT(*) AS purchases_count FROM user_events WHERE event_type='purchase' GROUP BY user_id HAVING COUNT(*)>=2;")
  ],"Объём платежей, уникальные покупатели и выручка различаются по зерну. События просмотра не должны увеличивать сумму покупки при JOIN, иначе результат математически неверен."),
  L("product-history","История действий и качество метрик","Уточняем порядок событий, находим последнюю активность и ранжируем платежи.",[
    "Для истории действий важно время event_at, но события могут происходить в одну секунду, поэтому дополняй ORDER BY уникальным event_id. LAG позволяет видеть предыдущую сумму покупки в истории того же пользователя.",
    "При поиске последней активности всех зарегистрированных используем LEFT JOIN и MAX, чтобы пользователь без событий не исчез. Такое отсутствие должно остаться NULL, а не автоматически превращаться в дату регистрации."
  ],"SELECT user_id,event_id,\n LAG(amount) OVER(PARTITION BY user_id ORDER BY event_at,event_id) AS previous_amount\nFROM user_events WHERE event_type='purchase';",
  "Почему в ORDER BY истории событий нужен дополнительный event_id?",["Чтобы сделать порядок воспроизводимым при равном времени","Чтобы удалить дубли","Чтобы ускорить любой запрос"],0,"Временная метка не всегда уникальна. Дополнительный ключ задаёт однозначное следование событий.",[
    T("product-16","Последняя активность","Для каждого зарегистрированного пользователя покажи user_id и время его последнего события last_event. У пользователя без событий оставь NULL.","SELECT u.user_id,MAX(e.event_at) AS last_event FROM app_users u LEFT JOIN user_events e ON e.user_id=u.user_id GROUP BY u.user_id;"),
    T("product-17","Рейтинг отдельных платежей","Для каждого платежа покажи его event_id, user_id, сумму и позицию position по убыванию суммы; при равной сумме первым должен быть меньший event_id.","SELECT event_id,user_id,amount,ROW_NUMBER() OVER(ORDER BY amount DESC,event_id) AS position FROM user_events WHERE event_type='purchase';"),
    T("product-18","Предыдущий платеж","Для каждого платежа покажи user_id, event_id и сумму предыдущей покупки этого пользователя previous_amount. Порядок — время, затем event_id; для первой покупки NULL.","SELECT user_id,event_id,LAG(amount) OVER(PARTITION BY user_id ORDER BY event_at,event_id) AS previous_amount FROM user_events WHERE event_type='purchase';")
  ],"Временной порядок важен для аналитики последовательности, но многие метрики всё равно требуют явного бизнес-окна. Не считай, что два события одного пользователя автоматически принадлежат одной сессии.")
 ])


];

// Preserve published IDs and progress: insert new lessons between existing lessons.
for(const item of curriculumAdditions){
 const module=modules.find(m=>m.id===item.module);
 if(!module)throw new Error('Unknown curriculum module: '+item.module);
 const before=item.after.startsWith('__before:');
 const anchor=before?item.after.slice('__before:'.length):item.after;
 const index=module.lessons.findIndex(lesson=>lesson.id===anchor);
 if(index<0)throw new Error('Curriculum insertion anchor not found: '+item.id+' after '+item.after);
 module.lessons.splice(index+(before?0:1),0,item.lesson);
}
export const lessons=modules.flatMap(module=>module.lessons.map((lesson,index)=>({...lesson,moduleId:module.id,moduleTitle:module.title,moduleIndex:modules.indexOf(module),lessonIndex:index})));
export const tasks=lessons.flatMap(lesson=>lesson.tasks.map(task=>({...task,lessonId:lesson.id,moduleId:lesson.moduleId})));
export const lessonById=Object.fromEntries(lessons.map(lesson=>[lesson.id,lesson]));
export const taskById=Object.fromEntries(tasks.map(task=>[task.id,task]));
export const moduleById=Object.fromEntries(modules.map(module=>[module.id,module]));
